BEGIN;
ON CONFLICT (id) DO UPDATE SET booking_status = EXCLUDED.booking_status, payment_status = EXCLUDED.payment_status, updated_at = NOW();

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO UPDATE SET payment_status = EXCLUDED.payment_status, updated_at = NOW();

SELECT setval(pg_get_serial_sequence('bookings', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM bookings), 1), true);
SELECT setval(pg_get_serial_sequence('booking_items', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM booking_items), 1), true);
SELECT setval(pg_get_serial_sequence('payments', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM payments), 1), true);

COMMIT;
